// =============================================================================
// EZER — the lock screen's dove mark
//
// The owner's pick from the Blender variants (path A, Cinzel, Oct 2026): a
// rendered dove swoops under the wordmark and lands on the top right of the R
// while EZER fades in. Both are images so they line up with the approved
// render exactly: a white Cinzel wordmark tinted per theme, and a sprite
// sheet of the flight (scale and fade-in baked into each cell). Frame data and
// the PNGs are generated by E:\ezer-dove\work\export_app.py. Rerun it after a
// re-render rather than nudging numbers here.
// =============================================================================

import React, { useEffect, useState } from 'react';
import { Image, View } from 'react-native';
import Animated, {
  cancelAnimation,
  Easing,
  useAnimatedStyle,
  useReducedMotion,
  useSharedValue,
  withRepeat,
  withTiming,
} from 'react-native-reanimated';
import { useTheme } from '../utils/ThemeContext';
import { motion } from '../theme/type';
import { CELL, PERCH, WORD, XY } from './doveFrames';
import { HOVER } from './doveHoverFrames';

const SHEET = require('../assets/dove/dove-sheet.png');
const PERCHED = require('../assets/dove/dove-perch.png');
const WORDMARK = require('../assets/dove/wordmark-cinzel.png');
const HOVER_SHEET = require('../assets/dove/dove-hover.webp');
const LAST = XY.length - 1;

// On cream the white dove washes out, so light mode rings it with a faint
// brand-gold edge: the dove's own silhouette tinted and drawn at 8 small
// offsets behind it. Offsets are in dp, so the edge is the same at any size.
// DoveLoader.tsx draws its edge from these too.
export const EDGE = [[1, 0], [-1, 0], [0, 1], [0, -1], [0.7, 0.7], [-0.7, 0.7], [0.7, -0.7], [-0.7, -0.7]] as const;
export const EDGE_DP = 0.9;
export const EDGE_OPACITY = 0.6;

/** The dove's edge colour for the current theme, or null for none. */
export function useEdge(): string | null {
  const { mode, colors } = useTheme();
  return mode === 'light' ? colors.gold : null;
}

function Perched({ k, onLoad, edge: edgeOverride }: { k: number; onLoad?: () => void; edge?: string | null }) {
  const themeEdge = useEdge();
  const edge = edgeOverride === undefined ? themeEdge : edgeOverride;
  const box = { position: 'absolute' as const, left: PERCH.x * k, top: PERCH.y * k, width: PERCH.w * k, height: PERCH.h * k };
  return (
    <>
      {edge &&
        EDGE.map(([dx, dy], i) => (
          <Image
            key={i}
            source={PERCHED}
            style={[box, { tintColor: edge, opacity: EDGE_OPACITY, transform: [{ translateX: dx * EDGE_DP }, { translateY: dy * EDGE_DP }] }]}
          />
        ))}
      <Image source={PERCHED} style={box} onLoad={onLoad} />
    </>
  );
}

/** The wordmark with the dove on the R. `width` is the wordmark's width in dp;
 *  the dove sits above that box (0.36 of the width), outside its layout.
 *  `ink` overrides the theme's word colour (onboarding is always dark). */
export function DoveMark({
  width,
  perched = true,
  onLoad,
  ink,
}: {
  width: number;
  perched?: boolean;
  onLoad?: () => void;
  ink?: string;
}) {
  const { colors } = useTheme();
  const edge = useEdge();
  const k = width / WORD.w;
  return (
    // needsOffscreenAlphaCompositing: when a parent fades (the keypad, the
    // lift), Android otherwise fades each of the 8 gold edge copies and the
    // white dove separately, and the gold shows through the dove as a blob.
    <View
      style={{ width, height: WORD.h * k }}
      needsOffscreenAlphaCompositing={perched && !!edge}
      accessible
      accessibilityRole="image"
      accessibilityLabel="EZER"
    >
      <Image source={WORDMARK} style={{ width, height: WORD.h * k, tintColor: ink ?? colors.ink }} onLoad={onLoad} />
      {perched && <Perched k={k} />}
    </View>
  );
}

/**
 * The flight. Plays once over `duration` ms when `play` turns true, ending on
 * the same pose DoveMark draws, so swapping to DoveMark afterwards doesn't
 * move the dove. Hidden until then; `onLoad` reports the sprite sheet decoded,
 * so the caller can hold the start until there is something to see.
 * The wordmark's own opacity is the caller's (LockGate's existing fade).
 */
export function DoveFlight({
  width,
  duration,
  play,
  onLoad,
  edge: edgeOverride,
}: {
  width: number;
  duration: number;
  play: boolean;
  onLoad?: () => void;
  /** null: no gold edge whatever the theme (onboarding's fixed dark design). */
  edge?: string | null;
}) {
  const reduced = useReducedMotion();
  const themeEdge = useEdge();
  const edge = edgeOverride === undefined ? themeEdge : edgeOverride;
  const k = width / WORD.w;
  const f = useSharedValue(0);
  useEffect(() => {
    if (play) f.value = withTiming(LAST, { duration, easing: Easing.linear });
  }, [f, duration, play]);

  // The cell window moves along the path; the sheet slides inside it.
  const box = useAnimatedStyle(() => {
    const i = Math.min(LAST, Math.round(f.value));
    return { transform: [{ translateX: XY[i][0] * k }, { translateY: XY[i][1] * k }] };
  });
  const sheet = useAnimatedStyle(() => {
    const i = Math.min(LAST, Math.round(f.value));
    return { transform: [{ translateX: -(i % CELL.cols) * CELL.w * k }, { translateY: -Math.floor(i / CELL.cols) * CELL.h * k }] };
  });

  // Reduced motion: no travel, the dove is simply there.
  if (reduced) {
    return <Perched k={k} onLoad={onLoad} edge={edge} />;
  }
  const size = { width: CELL.w * CELL.cols * k, height: CELL.h * CELL.rows * k };
  // Cells carry a 2px transparent margin, so the edge copies stay inside them.
  return (
    <Animated.View
      pointerEvents="none"
      needsOffscreenAlphaCompositing={!!edge}
      style={[{ position: 'absolute', left: 0, top: 0, width: CELL.w * k, height: CELL.h * k, overflow: 'hidden', opacity: play ? 1 : 0 }, box]}
    >
      {edge &&
        EDGE.map(([dx, dy], i) => (
          <Animated.View key={i} style={{ position: 'absolute', left: dx * EDGE_DP, top: dy * EDGE_DP, opacity: EDGE_OPACITY }}>
            <Animated.Image source={SHEET} style={[size, { tintColor: edge }, sheet]} />
          </Animated.View>
        ))}
      <Animated.Image source={SHEET} style={[size, sheet]} onLoad={onLoad} />
    </Animated.View>
  );
}

const hoverSize = (k: number) => ({ width: HOVER.w * HOVER.cols * k, height: HOVER.h * HOVER.rows * k });
// Past this the sheet is late: the dove stays perched for the whole wait
// rather than switching mid-way (a late take-off reads as a freeze then a jump).
const HOVER_CAP_MS = 200;
const TAKEOFF_MS = 200;
const TAKEOFF_EASE = Easing.bezier(...motion.easeOut);

/** The hover sheet, invisible. LockGate mounts it while the keypad is up so
 *  the sheet is decoded (and in the image cache) before the passcode is
 *  accepted, and DoveHover can take off on its first frame. */
export function DoveHoverPreload({ width }: { width: number }) {
  const reduced = useReducedMotion();
  if (reduced) return null;
  // pointerEvents none: it sits over part of the keypad and must not take its taps.
  return (
    <View pointerEvents="none" style={{ position: 'absolute', left: 0, top: 0, opacity: 0 }}>
      <Image source={HOVER_SHEET} style={hoverSize(width / WORD.w)} />
    </View>
  );
}

/**
 * The wait after the passcode: the dove takes off from the R and flaps in
 * place above it (the "hover" loader render, E:\ezer-dove\work\export_hover.py).
 * Loops while mounted; LockGate mounts it only for that phase.
 * Take-off: the loop starts on frame 0, the pose closest to the perched dove,
 * with the cell transformed (HOVER.t0, from the exporter) so that frame sits
 * exactly over the perched dove, and eases to the hover box over TAKEOFF_MS
 * while it flaps. So there is no frozen beat and no jump. Until the sheet
 * decodes the perched dove holds the R (same pose, so the swap is invisible);
 * if it misses HOVER_CAP_MS it stays perched for the whole phase.
 */
export function DoveHover({ width }: { width: number }) {
  const reduced = useReducedMotion();
  const edge = useEdge();
  const k = width / WORD.w;
  const [state, setState] = useState<'wait' | 'fly' | 'perch'>('wait');
  useEffect(() => {
    const t = setTimeout(() => setState(s => (s === 'wait' ? 'perch' : s)), HOVER_CAP_MS);
    return () => clearTimeout(t);
  }, []);
  const f = useSharedValue(0);
  const up = useSharedValue(0);
  useEffect(() => {
    if (reduced || state !== 'fly') return;
    up.value = withTiming(1, { duration: TAKEOFF_MS, easing: TAKEOFF_EASE });
    f.value = withRepeat(withTiming(HOVER.n, { duration: (HOVER.n / HOVER.fps) * 1000, easing: Easing.linear }), -1);
    return () => {
      cancelAnimation(f);
      cancelAnimation(up);
    };
  }, [f, up, reduced, state]);
  const cell = useAnimatedStyle(() => {
    const r = 1 - up.value;
    return { transform: [{ translateX: HOVER.t0.x * k * r }, { translateY: HOVER.t0.y * k * r }, { scale: 1 + (HOVER.t0.s - 1) * r }] };
  });
  const sheet = useAnimatedStyle(() => {
    const i = Math.floor(f.value) % HOVER.n;
    return { transform: [{ translateX: -(i % HOVER.cols) * HOVER.w * k }, { translateY: -Math.floor(i / HOVER.cols) * HOVER.h * k }] };
  });

  if (reduced) return <Perched k={k} />;
  const size = hoverSize(k);
  return (
    <>
      {state !== 'fly' && <Perched k={k} />}
      {state !== 'perch' && (
        <Animated.View
          pointerEvents="none"
          needsOffscreenAlphaCompositing={!!edge}
          style={[{ position: 'absolute', left: HOVER.x * k, top: HOVER.y * k, width: HOVER.w * k, height: HOVER.h * k, overflow: 'hidden', opacity: state === 'fly' ? 1 : 0 }, cell]}
        >
          {edge &&
            EDGE.map(([dx, dy], i) => (
              <View key={i} style={{ position: 'absolute', left: dx * EDGE_DP, top: dy * EDGE_DP, opacity: EDGE_OPACITY }}>
                <Animated.Image source={HOVER_SHEET} style={[size, { tintColor: edge }, sheet]} />
              </View>
            ))}
          <Animated.Image source={HOVER_SHEET} style={[size, sheet]} onLoad={() => setState(s => (s === 'wait' ? 'fly' : s))} />
        </Animated.View>
      )}
    </>
  );
}
